from pathlib import Path
code = '''import base64
import hashlib
import hmac


def verify_webhook(raw_body: bytes, hmac_header: str | None, secret: str) -> bool:
    if hmac_header is None:
        return False
    if not isinstance(hmac_header, str):
        return False
    if not hmac_header:
        return False
    if not hmac_header.isascii():
        return False

    digest = hmac.new(secret.encode("utf-8"), raw_body, hashlib.sha256).digest()
    expected = base64.b64encode(digest).decode("ascii")
    return hmac.compare_digest(hmac_header, expected)
'''
Path('/work/shopify_webhook.py').write_text(code)
